+/** Theoretical use from sales vs actual consume movements per item between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const round3 = (n) => Math.round(n * 1000) / 1000;
+  const dishById = new Map((store.data.dishes ?? []).map((d) => [d.id, d]));
+  const recipeById = new Map((store.data.recipes ?? []).map((r) => [r.id, r]));
+  const theoretical = new Map();
+  for (const sale of store.data.sales ?? []) {
+    const day = dayOf(sale.soldAt);
+    if (day < from || day > to) continue;
+    const dish = dishById.get(sale.dishId);
+    if (!dish) continue;
+    const recipe = recipeById.get(dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, sale.qty)) {
+      theoretical.set(n.itemId, (theoretical.get(n.itemId) ?? 0) + n.qty);
+    }
+  }
+
+  const batchById = new Map(store.data.batches.map((b) => [b.id, b]));
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const batch = batchById.get(m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+
+  const out = [];
+  for (const item of listItems(store)) {
+    const th = round3(theoretical.get(item.id) ?? 0);
+    const ac = round3(actual.get(item.id) ?? 0);
+    if (th <= 0 && ac <= 0) continue;
+    out.push({
+      itemId: item.id,
+      name: item.name,
+      unit: item.unit,
+      theoretical: th,
+      actual: ac,
+      diff: round3(ac - th) || 0,
+    });
+  }
+  return out;
+}
